#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Edge {
    int u, v;
    ll w;
    bool operator<(const Edge& other) const {
        return w < other.w;
    }
};

struct DSU {
    vector<int> p, sz;
    DSU(int n) : p(n), sz(n, 1) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    ll D;
    cin >> N >> D;
    vector<ll> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    // For edge(i, j), i < j:
    // cost = A[i] + A[j] + (j - i) * D
    //      = (A[i] - i*D) + (A[j] + j*D)
    //
    // In the MST, it is sufficient to consider, for each j,
    // an edge from j to the best i on the left minimizing A[i] - i*D,
    // and symmetrically for each i, an edge to the best j on the right
    // minimizing A[j] + j*D.
    //
    // We can generate these O(N) candidate edges and run Kruskal.

    vector<Edge> edges;
    edges.reserve(2 * N);

    // Left best for each position
    ll bestVal = (1LL << 62);
    int bestIdx = -1;
    for (int j = 0; j < N; ++j) {
        if (bestIdx != -1) {
            ll w = A[j] + 1LL * j * D + bestVal;
            edges.push_back({bestIdx, j, w});
        }
        ll cur = A[j] - 1LL * j * D;
        if (cur < bestVal) {
            bestVal = cur;
            bestIdx = j;
        }
    }

    // Right best for each position
    bestVal = (1LL << 62);
    bestIdx = -1;
    for (int i = N - 1; i >= 0; --i) {
        if (bestIdx != -1) {
            ll w = A[i] - 1LL * i * D + bestVal;
            edges.push_back({i, bestIdx, w});
        }
        ll cur = A[i] + 1LL * i * D;
        if (cur < bestVal) {
            bestVal = cur;
            bestIdx = i;
        }
    }

    sort(edges.begin(), edges.end());

    DSU dsu(N);
    ll ans = 0;
    int used = 0;
    for (const auto& e : edges) {
        if (dsu.unite(e.u, e.v)) {
            ans += e.w;
            used++;
            if (used == N - 1) break;
        }
    }

    cout << ans << '\n';
    return 0;
}

