typedef long long ll;

typedef struct {
    int u, v;
    ll w;
} Edge;

static int cmp_edge(const void *a, const void *b) {
    ll x = ((const Edge*)a)->w;
    ll y = ((const Edge*)b)->w;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

typedef struct {
    int *p, *sz;
} DSU;

static void dsu_init(DSU *d, int n) {
    d->p = (int*)malloc(n * sizeof(int));
    d->sz = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        d->p[i] = i;
        d->sz[i] = 1;
    }
}

static int dsu_find(DSU *d, int x) {
    while (d->p[x] != x) {
        d->p[x] = d->p[d->p[x]];
        x = d->p[x];
    }
    return x;
}

static int dsu_union(DSU *d, int a, int b) {
    a = dsu_find(d, a);
    b = dsu_find(d, b);
    if (a == b) return 0;
    if (d->sz[a] < d->sz[b]) {
        int t = a; a = b; b = t;
    }
    d->p[b] = a;
    d->sz[a] += d->sz[b];
    return 1;
}

int main(void) {
    int N;
    ll D;
    if (scanf("%d %lld", &N, &D) != 2) return 0;

    ll *A = (ll*)malloc(N * sizeof(ll));
