    if (N == 1) {
        printf("0\n");
        free(A);
        return 0;
    }

    /*
      Edge cost:
        |i-j|*D + A[i] + A[j]

      For i < j:
        (A[i] - i*D) + (A[j] + j*D)
      For i > j:
        (A[i] + i*D) + (A[j] - j*D)

      Using the cut property, for each city i it suffices to consider:
      - best city on the left minimizing A[j] - j*D
      - best city on the right minimizing A[j] + j*D

      These O(N) candidate edges contain some MST.
    */

    int *best_left = (int*)malloc(N * sizeof(int));
    int *best_right = (int*)malloc(N * sizeof(int));

    best_left[0] = -1;
    int mn_idx = 0;
    ll mn_val = A[0] - (ll)0 * D;
    for (int i = 1; i < N; i++) {
        best_left[i] = mn_idx;
        ll cur = A[i] - (ll)i * D;
        if (cur < mn_val) {
            mn_val = cur;
            mn_idx = i;
        }
    }

    best_right[N - 1] = -1;
    mn_idx = N - 1;
    mn_val = A[N - 1] + (ll)(N - 1) * D;
    for (int i = N - 2; i >= 0; i--) {
        best_right[i] = mn_idx;
        ll cur = A[i] + (ll)i * D;
        if (cur < mn_val) {
            mn_val = cur;
            mn_idx = i;
        }
    }

    Edge *edges = (Edge*)malloc((2LL * N) * sizeof(Edge));
    int m = 0;

    for (int i = 0; i < N; i++) {
        if (best_left[i] != -1) {
            int j = best_left[i];
            edges[m].u = i;
            edges[m].v = j;
            edges[m].w = (ll)(i - j) * D + A[i] + A[j];
            m++;
        }
        if (best_right[i] != -1) {
            int j = best_right[i];
            edges[m].u = i;
            edges[m].v = j;
            edges[m].w = (ll)(j - i) * D + A[i] + A[j];
            m++;
        }
    }

    qsort(edges, m, sizeof(Edge), cmp_edge);

    DSU dsu;
    dsu_init(&dsu, N);

    ll ans = 0;
    int used = 0;
    for (int i = 0; i < m && used < N - 1; i++) {
        if (dsu_union(&dsu, edges[i].u, edges[i].v)) {
            ans += edges[i].w;
            used++;
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(best_left);
    free(best_right);
    free(edges);
    free(dsu.p);
    free(dsu.sz);
