import java.io.*;
import java.util.*;

public class Main {
    // Edge for MST
    static class Edge implements Comparable<Edge> {
        int u, v;
        long w;
        Edge(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
        public int compareTo(Edge other) {
            return Long.compare(this.w, other.w);
        }
    }

    // DSU / Union-Find
    static class DSU {
        int[] p, sz;
        DSU(int n) {
            p = new int[n];
            sz = new int[n];
            for (int i = 0; i < n; i++) {
                p[i] = i;
                sz[i] = 1;
            }
        }
        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }
        boolean union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return false;
            if (sz[a] < sz[b]) {
                int t = a; a = b; b = t;
            }
            p[b] = a;
            sz[a] += sz[b];
            return true;
        }
    }

    static int N;
    static long D;
    static long[] A;
    static ArrayList<Edge> edges = new ArrayList<>();

    // Segment tree storing minimum value and its index
    static class SegTree {
        long[] val;
        int[] idx;
        int n;

        SegTree(long[] arr) {
            int sz = arr.length;
            n = 1;
            while (n < sz) n <<= 1;
            val = new long[n << 1];
            idx = new int[n << 1];
            Arrays.fill(val, Long.MAX_VALUE / 4);
            Arrays.fill(idx, -1);
            for (int i = 0; i < sz; i++) {
                val[n + i] = arr[i];
                idx[n + i] = i;
            }
            for (int i = n - 1; i >= 1; i--) pull(i);
        }

        void pull(int i) {
            if (val[i << 1] <= val[i << 1 | 1]) {
                val[i] = val[i << 1];
                idx[i] = idx[i << 1];
            } else {
                val[i] = val[i << 1 | 1];
                idx[i] = idx[i << 1 | 1];
            }
        }

        long[] query(int l, int r) { // [l, r)
            long bestVal = Long.MAX_VALUE / 4;
            int bestIdx = -1;
            l += n;
            r += n;
            while (l < r) {
                if ((l & 1) == 1) {
                    if (val[l] < bestVal) {
                        bestVal = val[l];
                        bestIdx = idx[l];
                    }
                    l++;
                }
                if ((r & 1) == 1) {
                    --r;
                    if (val[r] < bestVal) {
                        bestVal = val[r];
                        bestIdx = idx[r];
                    }
                }
                l >>= 1;
                r >>= 1;
            }
            return new long[]{bestVal, bestIdx};
        }
    }

    static void solveRange(int l, int r, SegTree leftTree, SegTree rightTree) {
        if (r - l <= 1) return;
        int m = (l + r) >>> 1;

        // For each i in [l, m), best j in [m, r) minimizes A[j] + j*D
        long[] q1 = rightTree.query(m, r);
        int bestRight = (int) q1[1];
        for (int i = l; i < m; i++) {
            long w = A[i] + A[bestRight] + (long)(bestRight - i) * D;
            edges.add(new Edge(i, bestRight, w));
        }

        // For each j in [m, r), best i in [l, m) minimizes A[i] - i*D
        long[] q2 = leftTree.query(l, m);
        int bestLeft = (int) q2[1];
        for (int j = m; j < r; j++) {
            long w = A[bestLeft] + A[j] + (long)(j - bestLeft) * D;
            edges.add(new Edge(bestLeft, j, w));
        }

        solveRange(l, m, leftTree, rightTree);
        solveRange(m, r, leftTree, rightTree);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        D = fs.nextLong();
        A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        long[] leftBase = new long[N];   // A[i] - i*D
        long[] rightBase = new long[N];  // A[i] + i*D
        for (int i = 0; i < N; i++) {
            leftBase[i] = A[i] - (long)i * D;
            rightBase[i] = A[i] + (long)i * D;
        }

        SegTree leftTree = new SegTree(leftBase);
        SegTree rightTree = new SegTree(rightBase);

